#!/usr/bin/env node
/**
 * make_pck.mjs — Create a Godot 4.4 PCK file without the Godot editor.
 *
 * Writes the binary PCK format directly, embedding a minimal project
 * (project.godot + main.tscn + main.gd) that shows a bouncing blue rectangle.
 *
 * Usage: node make_pck.mjs [output.pck]
 */

import { writeFileSync } from 'fs';
import { createHash } from 'crypto';

// ─── Godot project files ─────────────────────────────────────────────────

const files = {
  'project.godot': `; Engine configuration file.
; Generated by make_pck.mjs for wasmcart testing.

[application]

config/name="Hello Godot"
run/main_scene="res://main.tscn"
config/features=PackedStringArray("4.4")

[display]

window/size/viewport_width=640
window/size/viewport_height=480

[rendering]

renderer/rendering_method="gl_compatibility"
`,

  'main.tscn': `[gd_scene load_steps=2 format=3]

[ext_resource type="Script" path="res://main.gd" id="1"]

[node name="Main" type="Node2D"]
script = ExtResource("1")

[node name="ColorRect" type="ColorRect" parent="."]
offset_right = 100.0
offset_bottom = 100.0
color = Color(0.2, 0.6, 1.0, 1.0)
`,

  'main.gd': `extends Node2D

var speed := 200.0
var vel := Vector2(200.0, 140.0)

func _process(delta: float) -> void:
\tvar rect := $ColorRect
\trect.position += vel * delta

\tvar vp := get_viewport_rect().size
\tif rect.position.x < 0.0 or rect.position.x + rect.size.x > vp.x:
\t\tvel.x = -vel.x
\t\trect.position.x = clampf(rect.position.x, 0.0, vp.x - rect.size.x)
\tif rect.position.y < 0.0 or rect.position.y + rect.size.y > vp.y:
\t\tvel.y = -vel.y
\t\trect.position.y = clampf(rect.position.y, 0.0, vp.y - rect.size.y)
`,
};

// ─── PCK format constants ─────────────────────────────────────────────────

const PACK_HEADER_MAGIC = 0x43504447; // "GDPC"
const PACK_FORMAT_VERSION = 2;
const VERSION_MAJOR = 4;
const VERSION_MINOR = 4;
const VERSION_PATCH = 0;
const ALIGNMENT = 32;

function pad(n, alignment) {
  const rest = n % alignment;
  return rest > 0 ? alignment - rest : 0;
}

function md5(data) {
  return createHash('md5').update(data).digest();
}

// ─── Build PCK ────────────────────────────────────────────────────────────

const fileEntries = Object.entries(files).map(([path, content]) => ({
  path,
  data: Buffer.from(content, 'utf-8'),
}));

// Calculate sizes for the directory section
// Header: 4+4+4+4+4+4 = 24 bytes, then u64 files_base = 8, then 16*4=64 reserved
// Total fixed header: 24 + 8 + 64 = 96 bytes
// Directory: u32 file_count, then per-file entries

let dirSize = 4; // file_count
for (const entry of fileEntries) {
  const pathBytes = Buffer.from(entry.path, 'utf-8');
  const pathPad = pad(pathBytes.length, 4);
  // u32 path_len + path_bytes + pad + u64 offset + u64 size + 16 md5 + u32 flags
  dirSize += 4 + pathBytes.length + pathPad + 8 + 8 + 16 + 4;
}

const headerSize = 96; // fixed header before directory
const dirPad = pad(headerSize + dirSize, ALIGNMENT);
const filesBase = headerSize + dirSize + dirPad;

// Calculate file offsets (relative to filesBase)
let dataOffset = 0;
const fileOffsets = [];
for (const entry of fileEntries) {
  fileOffsets.push(dataOffset);
  dataOffset += entry.data.length;
  dataOffset += pad(dataOffset, ALIGNMENT);
}

const totalSize = filesBase + dataOffset;
const buf = Buffer.alloc(totalSize);
let pos = 0;

function writeU32(val) { buf.writeUInt32LE(val, pos); pos += 4; }
function writeU64(val) { buf.writeBigUInt64LE(BigInt(val), pos); pos += 8; }
function writeBytes(data) { data.copy(buf, pos); pos += data.length; }
function writeZeros(n) { buf.fill(0, pos, pos + n); pos += n; }

// ── Header ──
writeU32(PACK_HEADER_MAGIC);
writeU32(PACK_FORMAT_VERSION);
writeU32(VERSION_MAJOR);
writeU32(VERSION_MINOR);
writeU32(VERSION_PATCH);
writeU32(0); // flags

// files_base (u64)
writeU64(filesBase);

// 16 reserved u32s (64 bytes)
writeZeros(64);

// ── Directory ──
writeU32(fileEntries.length);

for (let i = 0; i < fileEntries.length; i++) {
  const entry = fileEntries[i];
  const pathBytes = Buffer.from(entry.path, 'utf-8');
  const pathPad = pad(pathBytes.length, 4);

  writeU32(pathBytes.length + pathPad);
  writeBytes(pathBytes);
  if (pathPad > 0) writeZeros(pathPad);

  writeU64(fileOffsets[i]); // offset relative to files_base
  writeU64(entry.data.length); // size
  writeBytes(md5(entry.data)); // md5
  writeU32(0); // flags
}

// Pad to alignment before file data
const currentDirPad = pad(pos, ALIGNMENT);
if (currentDirPad > 0) writeZeros(currentDirPad);

// Verify we're at filesBase
if (pos !== filesBase) {
  console.error(`ERROR: pos=${pos} != filesBase=${filesBase}`);
  process.exit(1);
}

// ── File data ──
for (const entry of fileEntries) {
  writeBytes(entry.data);
  const dataPad = pad(pos, ALIGNMENT);
  if (dataPad > 0) writeZeros(dataPad);
}

// Write output
const output = process.argv[2] || 'game.pck';
writeFileSync(output, buf.subarray(0, pos));
console.log(`Created ${output} (${pos} bytes, ${fileEntries.length} files)`);
for (const entry of fileEntries) {
  console.log(`  ${entry.path} (${entry.data.length} bytes)`);
}
